export type Actor = 'user' | 'agent';

export type LayerType = 'raster' | 'vector' | 'ai-generated';

/**
 * A layer stores exactly one kind of content:
 * - `fabric`: a serialized Fabric.js object produced by the brush tool.
 * - `svg`: markup generated by the AI agent.
 *
 * The daemon persists this value as JSON in `layers.content`.
 */
export type LayerContent =
  | { kind: 'fabric'; json: string }
  | { kind: 'svg'; svg: string };

export interface LayerMetadata {
  createdBy: Actor;
  createdAt: number;
  prompt?: string;
}

export interface Layer {
  id: string;
  canvasId: string;
  name: string;
  type: LayerType;
  zIndex: number;
  visible: boolean;
  opacity: number;
  content: LayerContent;
  metadata: LayerMetadata;
  createdAt: number;
}

export interface Canvas {
  id: string;
  name: string;
  width: number;
  height: number;
  backgroundColor: string;
  revision: number;
  createdAt: number;
  updatedAt: number;
}

export interface CanvasDocument extends Canvas {
  layers: Layer[];
}

export interface CreateLayerInput {
  name: string;
  type: LayerType;
  content: LayerContent;
  visible?: boolean;
  opacity?: number;
  zIndex?: number;
  metadata?: Partial<LayerMetadata>;
}

export interface UpdateLayerPatch {
  name?: string;
  visible?: boolean;
  opacity?: number;
  zIndex?: number;
}

export type PaintAction =
  | { type: 'canvas_create_layer'; layer: CreateLayerInput }
  | { type: 'canvas_update_layer'; layerId: string; patch: UpdateLayerPatch }
  | { type: 'canvas_delete_layer'; layerId: string };

export interface ApplyActionRequest {
  actor: Actor;
  action: PaintAction;
  expectedRevision?: number;
}

export interface ApplyActionResponse {
  canvas: CanvasDocument;
}

export interface CanvasSnapshot {
  id: string;
  canvasId: string;
  revision: number;
  actor: Actor;
  action: string;
  timestamp: number;
  state: string;
}

export interface SnapshotChangedEvent {
  type: 'snapshot_changed';
  canvasId: string;
  revision: number;
}

export interface CreateCanvasRequest {
  name?: string;
  width?: number;
  height?: number;
  backgroundColor?: string;
}

export interface AiChatRequest {
  canvasId?: string;
  message: string;
}

export interface AiChatMessage {
  role: 'user' | 'assistant';
  content: string;
}

export interface ApiErrorBody {
  error: {
    code: string;
    message: string;
  };
}
